import { forbidden } from 'next/navigation'
import { verifyAdmin } from '@/app/lib/auth'

// The session check runs before any `await` on rendered children and there is no
// `loading.tsx` for this segment, so nothing has streamed yet when `forbidden()`
// throws. That's what lets Next.js send a real `403` status instead of a soft 200.
export default async function AdminPage() {
  const { isAdmin, session } = await verifyAdmin()

  if (!isAdmin) {
    forbidden()
  }

  return (
    <main>
      <h1>Admin Dashboard</h1>
      <p>Welcome, {session!.name}!</p>
    </main>
  )
}

